// Writes four tileable film-grain tiles to public/grain/grain-{0..3}.png.
// Grayscale, 8-bit, mean 128. Deterministic (seeded mulberry32) and built
// with node built-ins only, so the tiles can be regenerated byte-identical.
//
//   node tools/make-grain.mjs [--size 512]
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const args = process.argv.slice(2);
const sizeArg = args.indexOf("--size");
const SIZE = sizeArg >= 0 ? Number(args[sizeArg + 1]) : 512;
const TILES = 4;

const mulberry32 = (seed) => {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
};

/** Standard normal samples (Box-Muller). */
const gaussian = (rnd) => () => {
  const u = Math.max(1e-12, rnd());
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * rnd());
};

/** Separable [1 2 1]/4 blur with wrap-around, so the tile stays seamless. */
const blur = (src, n) => {
  const tmp = new Float64Array(n * n);
  const out = new Float64Array(n * n);
  for (let y = 0; y < n; y++)
    for (let x = 0; x < n; x++)
      tmp[y * n + x] = (src[y * n + ((x + n - 1) % n)] + 2 * src[y * n + x] + src[y * n + ((x + 1) % n)]) / 4;
  for (let y = 0; y < n; y++)
    for (let x = 0; x < n; x++)
      out[y * n + x] = (tmp[((y + n - 1) % n) * n + x] + 2 * tmp[y * n + x] + tmp[((y + 1) % n) * n + x]) / 4;
  return out;
};

/** Film grain: fine silver specks over slightly clumped dye clouds. */
const grainTile = (seed, n) => {
  const g = gaussian(mulberry32(seed));
  const fine = Float64Array.from({ length: n * n }, g);
  const clumps = blur(blur(Float64Array.from({ length: n * n }, g), n), n);
  const v = fine.map((f, i) => 0.9 * f + 0.9 * clumps[i]);
  let mean = 0;
  for (const x of v) mean += x;
  mean /= v.length;
  let sd = 0;
  for (const x of v) sd += (x - mean) ** 2;
  sd = Math.sqrt(sd / v.length);
  const px = new Uint8Array(n * n);
  for (let i = 0; i < v.length; i++) px[i] = Math.max(0, Math.min(255, Math.round(128 + ((v[i] - mean) / sd) * 42)));
  return px;
};

// ---------------------------------------------------------------- PNG

const CRC_TABLE = Array.from({ length: 256 }, (_, n) => {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  return c >>> 0;
});
const crc32 = (buf) => {
  let c = 0xffffffff;
  for (const b of buf) c = CRC_TABLE[(c ^ b) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
};
const chunk = (type, data) => {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type, "ascii"), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body));
  return Buffer.concat([len, body, crc]);
};
const encodeGray = (px, n) => {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(n, 0);
  ihdr.writeUInt32BE(n, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 0; // grayscale
  const raw = Buffer.alloc(n * (n + 1));
  for (let y = 0; y < n; y++) {
    raw[y * (n + 1)] = 0; // filter: none
    raw.set(px.subarray(y * n, (y + 1) * n), y * (n + 1) + 1);
  }
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr),
    chunk("IDAT", zlib.deflateSync(raw, { level: 9 })),
    chunk("IEND", Buffer.alloc(0)),
  ]);
};

const outDir = path.join(root, "public", "grain");
fs.mkdirSync(outDir, { recursive: true });
for (let i = 0; i < TILES; i++) {
  const file = path.join(outDir, `grain-${i}.png`);
  fs.writeFileSync(file, encodeGray(grainTile(0x5eed + i * 7919, SIZE), SIZE));
  console.log(path.relative(root, file));
}
